  var button=Walk(window).OfType<Button>().Single(b=>b.Content?.ToString()==session.Localize("create Reference"));button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(Node().Parameters["InitFlag"].GetInt32()==1&&Node().Parameters["FixInitPointX"].GetDouble()==0.0078125,"actual teach command writes source eight-parameter state");window.Close();Pump();Bind("InPointX","15");record=Execute();var fixture=record.Outputs["Position Correction Info"].As<FixtureValue>();Check(fixture.Reference.X==0.0078125&&fixture.Run.X==15,"actual repeated run retains locked reference");var scope=Field<ModuleExecutionScope>(shell,"executionScope").ForProcedure(doc.CurrentProcedureId);var display=plugin!.LastDisplay(Node(),doc.BaseDirectory,scope)!;Check(display.Graphics.Count==2,"source display publishes two independently configured points");Check(display.RecordText.Contains("BasePoint:(0.0078125,6)")&&display.RecordText.Contains("RunningPoint:(15,6)"),"source data record maps reference and run fields");
  var debug=(ToolEditorContext)Call(shell,"CreateToolEditorContext",id)!;var debugTask=debug.Run(Node().Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone()));Wait(debugTask);Check(debugTask.Result.Outputs["Position Correction Info"].As<FixtureValue>().Reference.X==0.0078125,"actual NodeDebug shares original module scope state");if(debug.Session is IAsyncDisposable disposer)Wait(disposer.DisposeAsync().AsTask());
