  string file=System.IO.Path.GetFullPath("analysis/b-fixture/host-solution/fixture.vsolution");System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(file)!);doc.Save(file);Check(Node().Parameters["FixRunPointX"].GetDouble()==15,"real Save reads latest native-style run cache");Check(Node().Parameters["FixInitPointX"].GetDouble()==(double)(float)0.007813,"real Save stores original six-place half-away reference");var edited=Node().Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());edited["FixInitAngle"]=JsonSerializer.SerializeToElement(2.5);doc.SetProcedureNodeParameters(doc.CurrentProcedureId,id,edited);var liveAfterSave=Execute().Outputs["Position Correction Info"].As<FixtureValue>();Check(liveAfterSave.Reference.X==0.0078125&&liveAfterSave.Reference.Angle==2.5,"Save then single parameter edit preserves other live fields while applying edited field");doc.Load(file);record=Execute();fixture=record.Outputs["Position Correction Info"].As<FixtureValue>();Check(record.Status==NodeRunStatus.Success&&fixture.Reference.X==(double)(float)0.007813&&fixture.Reference.ScaleX==0&&fixture.Run.ScaleX==1,"actual Save/Load preserves eight params and unsaved reference scale0");bool rejected=false;try{_=fixture.Transform(new(1,1));}catch(ArgumentException){rejected=true;}Check(rejected,"zero transport is distinct from safe inverse-transform consumer");scope=Field<ModuleExecutionScope>(shell,"executionScope").ForProcedure(doc.CurrentProcedureId);var old=Node();doc.DeleteNodes([id]);Check(plugin!.LastDisplay(old,doc.BaseDirectory,scope) is null,"real node delete releases scoped pose/display");
